import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, fract, sin, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Mesh, DirectionalLight, Color } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [
      { text: 'Features 2', role: 'headline', typography: { fontSize: 39 } },
    ];

  const group = new Group();
  group.name = 'features-card-2-label';

  const inner = new Group();
  group.add(inner);

  // -----------------------------
  // Backdrop chip: engineered gradient + subtle grain
  // -----------------------------
  const width = 1.6;
  const height = 1.0;

  const inkColor = vec3(new Color(colors.ink).r, new Color(colors.ink).g, new Color(colors.ink).b);
  const surfaceColor = vec3(new Color(colors.surface).r, new Color(colors.surface).g, new Color(colors.surface).b);

  const grainStrength = uniform(0.035);
  const grain = fract(
    sin(uv().x.mul(143.23).add(uv().y.mul(97.17)).mul(1.0))
      .mul(43758.5453)
  ).sub(0.5).mul(grainStrength);

  const gradientBase = mix(inkColor, surfaceColor, uv().y);
  const backdropColor = gradientBase.add(grain);

  const chipRoughness = uniform(0.58);
  const chipMetalness = uniform(0.32);
  const chipOpacity = uniform(0.0);

  const backdropMat = new MeshStandardNodeMaterial();
  backdropMat.colorNode = backdropColor;
  backdropMat.roughnessNode = chipRoughness;
  backdropMat.metalnessNode = chipMetalness;
  backdropMat.opacityNode = chipOpacity;
  backdropMat.transparent = true;

  const backdropGeo = new PlaneGeometry(width, height);
  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, 0);
  inner.add(backdropMesh);

  // -----------------------------
  // Decorative accent orb overlay (subtle, <=10% of frame)
  // -----------------------------
  const decorGeo = new PlaneGeometry(0.4, 0.4);
  const decorMat = new MeshBasicNodeMaterial();
  decorMat.transparent = true;
  const decorOpacity = uniform(0.0);
  decorMat.opacityNode = decorOpacity;

  const decorMesh = new Mesh(decorGeo, decorMat);
  decorMesh.position.set(width / 2 - 0.28, height / 2 - 0.28, 0.015);
  inner.add(decorMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      decorMat.colorNode = null;
      decorMat.map = tex;
      decorMat.needsUpdate = true;
    });
  }

  // -----------------------------
  // Rim light (accent-tinted, node-local, within cap)
  // -----------------------------
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.55);
  rimLight.position.set(-0.6, -0.4, 0.8);
  inner.add(rimLight);

  // -----------------------------
  // Text: "Features 2" headline
  // -----------------------------
  let textMesh = null;
  const headlineItem =
    items.find((i) => i.role === 'headline') ?? items[0] ?? { text: 'Features 2' };

  if (headlineItem && headlineItem.text) {
    textMesh = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: headlineItem.typography?.fontSize ?? 39,
      color: colors.paper,
      align: 'center',
    });
    textMesh.position.set(0, 0, 0.03);
    inner.add(textMesh);
  }

  // -----------------------------
  // Primitives (none specified — loop is defensive/no-op)
  // -----------------------------
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(inner, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // -----------------------------
  // Entrance motion: weighted-settle style, no idle loop (static composition)
  // -----------------------------
  inner.position.y = -0.12;

  const tl = gsap.timeline();
  tl.to(chipOpacity, { value: 1, duration: 0.6, ease: 'power2.out' }, 0);
  tl.to(decorOpacity, { value: 0.4, duration: 0.6, ease: 'power2.out' }, 0.05);
  tl.to(
    inner.position,
    { y: 0.03, duration: 0.9, ease: 'power4.out' },
    0
  );
  tl.to(
    inner.position,
    { y: 0, duration: 0.35, ease: 'power2.out' },
    0.9
  );

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    for (const h of primitiveHandles) {
      h.cleanup?.();
    }
    backdropGeo.dispose();
    backdropMat.dispose();
    decorGeo.dispose();
    decorMat.dispose();
    if (decorMat.map) decorMat.map.dispose();
    rimLight.dispose?.();
    if (textMesh) {
      textMesh.traverse?.((obj) => {
        obj.geometry?.dispose?.();
        obj.material?.dispose?.();
      });
    }
  };

  return group;
}
